import {plan,defaults,roadState,simulate} from './engine.js';
const $=id=>document.getElementById(id),fmt=n=>Number(n).toLocaleString('en-MY'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,result,stressResult,predictive,options={...defaults,closed_roads:[],closed_shelters:[]},view='overview',highlight=null,showRoads=true,showRoutes=true,timer,lastWeatherAttempt=0;
const titles={overview:['马来西亚灾难响应实验室','Klang–Shah Alam 示意网络 · 洪灾演练 · 数据时钟 09:00 MYT'],evacuation:['撤离路径与 PPS 分配','EVACUATION / SHELTERS · 透明呈现容量、可达性与安置缺口'],resources:['前线资源配置','RESOURCE ALLOCATION · 第一波到达建议，供指挥人员演练'],uncertainty:['不确定性与压力演练','STOCHASTIC MODELLING · 看见单一方案背后的波动'],sources:['数据、方法与研究路径','PROVENANCE / METHODS · 来源可追溯，假设可检查']};
const kindName={rescue_team:'救援队',medical_team:'医疗队',bus:'巴士'},reasonName={closed:'已关闭',unverified:'未核实',stale:'资料过期',hazard_excluded:'风险排除',available_exercise:'演练可用'};
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('toast').hidden=true,3500);}
function showView(name){if(!titles[name])name='overview';view=name;for(let el of document.querySelectorAll('.view'))el.hidden=el.id!=='view-'+name;document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===name);if(b.dataset.view===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('viewTitle').textContent=titles[name][0];$('viewSubtitle').textContent=titles[name][1];history.replaceState(null,'','#'+name);if(name==='overview'&&data)renderMap();}
function readControls(){return {...options,pressure:+$('pressure').value,horizon_minutes:+$('horizon').value,shelter_scale:+$('shelterScale').value,congestion:+$('congestion').value,accessible_only:$('accessible').checked};}
function labels(){ $('pressureVal').value=(+$('pressure').value).toFixed(2)+'×';$('horizonVal').value=$('horizon').value+' 分钟';$('shelterVal').value=Math.round(+$('shelterScale').value*100)+'%';$('congestionVal').value=(+$('congestion').value).toFixed(2)+'×';}
function syncControls(){for(let [id,key] of [['pressure','pressure'],['horizon','horizon_minutes'],['shelterScale','shelter_scale'],['congestion','congestion']])$(id).value=options[key];$('accessible').checked=options.accessible_only;labels();}
function calculate(){try{options=readControls();result=plan(data,options);highlight=null;render();$('planStatus').textContent='已重新计算 · 当前设置的静态分配';$('runBtn').textContent='重新计算方案 →';}catch(e){toast('计算未完成：'+e.message);}}
function render(){ $('kDemand').textContent=fmt(result.total_demand);$('kAssigned').textContent=fmt(result.assigned);$('kUnassigned').textContent=fmt(result.unassigned);$('kCoverage').textContent=(100*result.assigned/Math.max(1,result.total_demand)).toFixed(1)+'% 人口有模型分配去向';$('kResources').textContent=result.dispatch.assigned_units+' / '+result.dispatch.requested_units;$('kResourceNote').textContent='独立任务建议 · 不计撤离座位';renderMap();renderCommunities();renderCapacity();renderRoutes();renderRoads();renderResources();}
function renderCommunities(){let sorted=[...result.communities].sort((a,b)=>b.unassigned-a.unassigned);$('communityCards').innerHTML=sorted.map(c=>{let source=data.communities.find(x=>x.id===c.id);return `<div class="community-card"><span class="community-symbol">${esc(c.id.replace('Z',''))}</span><div><strong>${esc(source.name)}</strong><p>${fmt(c.population)} 人 · 需协助 ${source.priority_population} 人 · 已分配 ${c.assigned} 人</p></div><div class="gap ${c.unassigned?'':'none'}">${c.unassigned?fmt(c.unassigned):'已分配'}<small>${c.unassigned?'待解决人口':'模型分配完成'}</small></div></div>`;}).join('');}
function renderCapacity(){ $('capacityCards').innerHTML=result.shelters.map(s=>{let source=data.shelters.find(x=>x.id===s.id),ratio=s.available_capacity?s.assigned/s.available_capacity:0;return `<div class="capacity-row"><div class="capacity-row-head">${esc(source.name)}<span>${s.assigned} / ${s.available_capacity}</span></div><div class="bar-track"><span class="${ratio>=.95?'full':''}" style="width:${Math.min(100,ratio*100)}%"></span></div><small>${s.available_capacity?`剩余 ${s.available_capacity-s.assigned} 个模型名额`:'当前设置下不可用'}${!source.accessible?' · 未声明无障碍':''}</small></div>`;}).join('');$('shelterControls').innerHTML=data.shelters.map(s=>{let closed=options.closed_shelters.includes(s.id);return `<div class="shelter-control"><div><strong>${esc(s.name)}</strong><p>总容量 ${s.capacity} · 原有 ${s.occupied} 人<br>${s.accessible?'已声明无障碍':'无障碍状态不满足默认筛选'}</p></div><button class="toggle ${closed?'closed':''}" data-shelter="${esc(s.id)}" aria-pressed="${closed}">${closed?'已关闭 · 恢复':'关闭 PPS'}</button></div>`;}).join('');document.querySelectorAll('[data-shelter]').forEach(b=>b.onclick=()=>{let id=b.dataset.shelter;options.closed_shelters=options.closed_shelters.includes(id)?options.closed_shelters.filter(x=>x!==id):[...options.closed_shelters,id];calculate();toast('已更新模拟 PPS 可用性');});}
function renderRoutes(){ $('routesBody').innerHTML=result.routes.length?result.routes.map((r,i)=>`<tr class="route-row" tabindex="0" role="button" data-route="${i}" aria-label="查看 ${r.community} 至 ${r.shelter} 的 ${r.people} 人分配路径"><td>${esc(data.communities.find(c=>c.id===r.community).name)}</td><td>${esc(r.shelter)}</td><td>${fmt(r.people)}</td><td><span class="badge ${r.priority?'amber':'soft'}">${r.priority?'需协助':'一般'}</span></td><td>${r.minutes} min</td><td style="font-size:8px">${r.roads.map(esc).join(' → ')}</td></tr>`).join(''):'<tr><td colspan="6">没有可行分配。检查道路、PPS 和容量设置。</td></tr>';document.querySelectorAll('[data-route]').forEach(row=>{let select=()=>{highlight=result.routes[+row.dataset.route];showView('overview');$('mapInfo').textContent=`${highlight.community} → ${highlight.shelter} · ${highlight.people} 人 · ${highlight.minutes} 分钟假设行程；抽象走廊不用于导航。`;$('mapInfo').scrollIntoView({behavior:'smooth',block:'nearest'});};row.onclick=select;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});}
function renderRoads(){ $('excludedBadge').textContent=result.excluded_roads.length+' / '+data.roads.length+' 条排除';$('roadControls').innerHTML=data.roads.map(r=>{let state=roadState(r,data,options),manual=options.closed_roads.includes(r.id),disabled=r.status!=='verified_exercise'||state==='stale';return `<article class="road-card ${state!=='available_exercise'?'excluded':''}"><div><strong>${esc(r.id)}</strong><span class="badge ${state==='available_exercise'?'soft':'amber'}">${reasonName[state]}</span></div><p>${r.u} ↔ ${r.v} · ${r.capacity_per_hour} 人/小时<br>风险分数 ${(r.risk*options.pressure).toFixed(2)} / 阈值 ${options.risk_limit}</p><button data-road="${esc(r.id)}" ${disabled?'disabled':''}>${disabled?'需更新来源资料':manual?'解除演练关闭':'关闭此走廊'}</button></article>`;}).join('');document.querySelectorAll('[data-road]').forEach(b=>b.onclick=()=>{let id=b.dataset.road;options.closed_roads=options.closed_roads.includes(id)?options.closed_roads.filter(x=>x!==id):[...options.closed_roads,id];calculate();toast('已重算共享道路容量与分配');});}
function renderResources(){let assignments=result.dispatch.assignments;$('resourcesBody').innerHTML=assignments.length?assignments.map(r=>`<tr><td>${esc(r.asset)}</td><td>${kindName[r.type]}</td><td>${esc(data.communities.find(c=>c.id===r.community).name)}</td><td>${r.minutes} min</td><td style="font-size:8px">${r.roads.join(' → ')}</td></tr>`).join(''):'<tr><td colspan="5">当前没有可达且匹配能力的第一波资源。</td></tr>';$('resourceGaps').innerHTML=data.communities.map(c=>{let gaps=Object.entries(c.needs).map(([kind,n])=>[kind,Math.max(0,n-assignments.filter(a=>a.community===c.id&&a.type===kind).length)]).filter(([,n])=>n>0);return `<div class="resource-gap"><strong>${esc(c.name)}</strong>${gaps.length?`<div>${gaps.map(([k,n])=>`<span>${kindName[k]} × ${n}</span>`).join('')}</div>`:'<p>第一波所需单位均有建议资源</p>'}</div>`;}).join('');}
function renderMap(){let nodes=Object.fromEntries(data.nodes.map(n=>[n.id,n]));const pos=id=>{let n=nodes[id];return [(n.lon-101.40)/.23*740+65,(3.15-n.lat)/.18*430+55];};const path=(u,v)=>{let a=pos(u),b=pos(v);return `M ${a[0]} ${a[1]} L ${b[0]} ${b[1]}`;};let svg=`<defs><pattern id="grid" width="38" height="38" patternUnits="userSpaceOnUse"><path d="M38 0H0V38" fill="none" stroke="#dce5d4" stroke-width=".6"/></pattern><pattern id="blocks" width="100" height="83" patternUnits="userSpaceOnUse" patternTransform="rotate(-18)"><rect x="12" y="12" width="24" height="17" rx="2" fill="#e4eadb"/><rect x="45" y="12" width="36" height="17" rx="2" fill="#e7eddf"/><rect x="12" y="39" width="29" height="25" rx="2" fill="#e6ecdc"/><rect x="51" y="39" width="30" height="25" rx="2" fill="#e5ebda"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="2" stdDeviation="3" flood-opacity=".08"/></filter></defs><rect width="900" height="560" fill="#f0f4ea"/><rect width="900" height="560" fill="url(#grid)"/><rect width="900" height="560" fill="url(#blocks)" opacity=".75"/><path d="M50 -40 Q180 120 290 200 T410 340 T520 600" fill="none" stroke="#d4e5df" stroke-width="27"/><path d="M50 -40 Q180 120 290 200 T410 340 T520 600" fill="none" stroke="#c2dbd3" stroke-width="10"/><path d="M40 350 Q140 310 195 353 T360 402 Q450 437 490 515 L550 600 L0 600Z" fill="#b9d4cc" opacity=".20"/><ellipse cx="650" cy="120" rx="190" ry="80" fill="#dce8d0" opacity=".35"/><text x="75" y="500" font-size="9" fill="#abc1b2" font-family="sans-serif" letter-spacing="3">ILLUSTRATIVE TERRAIN</text><text x="600" y="80" font-size="8" fill="#a5b89f" font-family="sans-serif" letter-spacing="2">EXERCISE NETWORK</text>`;
if(showRoads)for(let r of data.roads){let state=roadState(r,data,options),excluded=state!=='available_exercise',a=pos(r.u),b=pos(r.v);svg+=`<g class="map-road" data-map-road="${r.id}" tabindex="0" role="button" aria-label="${r.id} ${reasonName[state]}"><title>${r.id}: ${reasonName[state]} — 演练走廊</title><path d="${path(r.u,r.v)}" stroke="white" stroke-width="8" fill="none"/><path d="${path(r.u,r.v)}" stroke="${excluded?'#c18a77':'#c5d0bb'}" stroke-width="${excluded?2:3}" ${excluded?'stroke-dasharray="5 5"':''} fill="none"/><path d="${path(r.u,r.v)}" stroke="transparent" stroke-width="18" fill="none"/><text x="${(a[0]+b[0])/2+4}" y="${(a[1]+b[1])/2-6}" fill="${excluded?'#b58b7b':'#9dac94'}" font-size="7" font-family="sans-serif">${r.id}</text></g>`;}
if(showRoutes){let used=highlight?highlight.roads:result.road_usage.filter(r=>r.people>0).map(r=>r.id);for(let rid of used){let r=data.roads.find(r=>r.id===rid),usage=result.road_usage.find(x=>x.id===rid);svg+=`<path d="${path(r.u,r.v)}" fill="none" stroke="${highlight?'#087b70':'#5b9e85'}" stroke-width="${highlight?5:2+(usage?.people||0)/180}" opacity="${highlight ? .95 : .78}" stroke-linecap="round" pointer-events="none"/>`;}}
for(let n of data.nodes.filter(n=>n.id.startsWith('J'))){let [x,y]=pos(n.id);svg+=`<circle cx="${x}" cy="${y}" r="3.5" fill="#f9fbf5" stroke="#a7b99a" stroke-width="1.5"/>`;}
for(let c of data.communities){let [x,y]=pos(c.node),res=result.communities.find(r=>r.id===c.id),label=c.name;svg+=`<g data-map-community="${c.id}" tabindex="0" role="button" aria-label="${label}，${res.unassigned} 人未分配" style="cursor:pointer"><title>${label} — ${c.population} 人，${res.unassigned} 人待解决</title><circle cx="${x}" cy="${y}" r="29" fill="${res.unassigned?'#cf9566':'#6fa88f'}" opacity=".10"/><circle cx="${x}" cy="${y}" r="19" fill="#fffaf0" stroke="${res.unassigned?'#bc8c59':'#7aaa8a'}" stroke-width="1.5" filter="url(#shadow)"/><text x="${x}" y="${y+4}" fill="#a17c50" text-anchor="middle" font-family="sans-serif" font-size="11" font-weight="600">${c.id.replace('Z','')}</text><rect x="${x-39}" y="${y+27}" width="78" height="33" rx="4" fill="#fffffff0"/><text x="${x}" y="${y+40}" text-anchor="middle" font-size="10" fill="#577762">${label}</text><text x="${x}" y="${y+52}" text-anchor="middle" font-size="7" fill="#95a68e">${c.population} 人 · ${res.unassigned} 待解决</text></g>`;}
for(let s of data.shelters){let [x,y]=pos(s.node),r=result.shelters.find(x=>x.id===s.id),open=r.available_capacity>0;svg+=`<g data-map-shelter="${s.id}" tabindex="0" role="button" aria-label="${s.name}，分配 ${r.assigned} 人" style="cursor:pointer"><title>${s.name} — ${r.assigned}/${r.available_capacity}</title><rect x="${x-15}" y="${y-15}" width="30" height="30" rx="6" fill="${open?'#27836d':'#a7b6a0'}" stroke="white" stroke-width="3" filter="url(#shadow)"/><path d="M${x-7} ${y+6} V${y-3} L${x} ${y-8} L${x+7} ${y-3} V${y+6} M${x-2} ${y+6} V${y} H${x+2} V${y+6}" fill="none" stroke="white" stroke-width="1.5"/><text x="${x}" y="${y+29}" text-anchor="middle" font-size="9" fill="#54816a">${s.id} · ${s.name}</text><text x="${x}" y="${y+41}" text-anchor="middle" font-size="7" fill="#8ea082">${r.assigned} / ${r.available_capacity}</text></g>`;}
let [dx,dy]=pos('D1');svg+=`<g><rect x="${dx-13}" y="${dy-13}" width="26" height="26" rx="5" fill="#22483d" stroke="white" stroke-width="2"/><text x="${dx}" y="${dy+4}" text-anchor="middle" font-size="11" fill="white">⊞</text><text x="${dx}" y="${dy-23}" text-anchor="middle" font-size="8" fill="#6e8c71">演练资源基地</text></g>`;$('map').innerHTML=svg;$('clearRoute').hidden=!highlight;document.querySelectorAll('[data-map-road],[data-map-community],[data-map-shelter]').forEach(el=>{let select=()=>{if(el.dataset.mapRoad){let r=data.roads.find(r=>r.id===el.dataset.mapRoad);$('mapInfo').textContent=`${r.id} · ${reasonName[roadState(r,data,options)]} · ${r.capacity_per_hour} 人/小时假设通量 · ${r.minutes} 分钟；在「撤离与 PPS」可关闭演练道路。`;}else if(el.dataset.mapCommunity){let c=data.communities.find(c=>c.id===el.dataset.mapCommunity),r=result.communities.find(r=>r.id===c.id);$('mapInfo').textContent=`${c.name} · 总需求 ${c.population} 人 · 已分配 ${r.assigned} 人 · 待解决 ${r.unassigned} 人；需协助群体未分配 ${r.priority_unassigned} 人。`;}else{let s=data.shelters.find(s=>s.id===el.dataset.mapShelter),r=result.shelters.find(r=>r.id===s.id);$('mapInfo').textContent=`${s.name}（虚构）· 当前名额 ${r.available_capacity} · 已分配 ${r.assigned} 人；不代表真实开放 PPS。`;}};el.onclick=select;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});}
function renderStress(s){$('stressP50').textContent=fmt(Math.round(s.unassigned_p50));$('stressP95').textContent=fmt(Math.round(s.unassigned_p95));$('stressProb').textContent=(s.probability_any_unassigned*100).toFixed(0)+'%';let values=s.unassigned_samples,min=Math.floor(Math.min(...values)/100)*100,max=Math.ceil(Math.max(...values)/100)*100+1,bins=10,step=(max-min)/bins,counts=Array(bins).fill(0);for(let x of values)counts[Math.min(bins-1,Math.floor((x-min)/step))]++;let top=Math.max(...counts,1),svg='';for(let j=0;j<5;j++){let y=220-j*45;svg+=`<line x1="45" x2="735" y1="${y}" y2="${y}" stroke="#e5eddf" stroke-width="1"/><text x="34" y="${y+3}" font-size="8" text-anchor="end" fill="#9baa8b">${Math.round(top*j/4)}</text>`;}for(let i=0;i<bins;i++){let h=counts[i]/top*180,x=48+i*68;svg+=`<rect x="${x}" y="${220-h}" width="53" height="${h}" rx="3" fill="${i>6?'#c3a275':'#6d9e7f'}"/><text x="${x+26}" y="${220-h-8}" text-anchor="middle" font-size="9" fill="#7b9576">${counts[i]}</text><text x="${x+25}" y="240" text-anchor="middle" font-size="8" fill="#9baa8b">${Math.round(min+i*step)}</text>`;}svg+='<text x="390" y="263" text-anchor="middle" font-size="9" fill="#8fa581">未分配人数（区间下界）</text>';$('histogram').innerHTML=svg;}
function download(text,filename,type='application/json'){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvDownload(){let rows=[['mode','as_of','community','shelter','priority','people','minutes','roads'],...result.routes.map(r=>[result.mode,result.as_of,r.community,r.shelter,r.priority,r.people,r.minutes,r.roads.join('|')])];download('\ufeff'+rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),'civicops_exercise_routes.csv','text/csv;charset=utf-8');}
async function fetchWeather(){if(Date.now()-lastWeatherAttempt<15000){toast('请稍后重试：官方 API 限流，每次请求至少间隔 15 秒。');return;}lastWeatherAttempt=Date.now();let btn=$('fetchWeather');btn.disabled=true;$('weatherStatus').textContent='正在尝试读取 api.data.gov.my，最多 20 条记录；演练模型保持独立。';$('weatherResults').replaceChildren();let controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{let r=await fetch('https://api.data.gov.my/weather/warning?limit=20',{signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);let rows=await r.json();if(!Array.isArray(rows))throw Error('响应结构不符合文档');let parse=x=>Date.parse(/(?:Z|[+-]\d\d:\d\d)$/.test(x)?x:x+'+08:00'),now=Date.now(),current=rows.filter(x=>Number.isFinite(parse(x.valid_from||''))&&Number.isFinite(parse(x.valid_to||''))&&parse(x.valid_from)<=now&&parse(x.valid_to)>=now);$('weatherStatus').textContent=`已于 ${new Date().toLocaleString('en-MY',{timeZone:'Asia/Kuala_Lumpur'})} MYT 读取 ${rows.length} 条记录，其中 ${current.length} 条在有效期内。这是最多 20 条的截取，不能代表全国完整预警状态；未导入演练路线。`;
for(let row of rows.slice(0,5)){let card=document.createElement('article');card.className='weather-card';let h=document.createElement('h3');h.textContent=row.heading_en||row.heading_bm||row.warning_issue?.title_en||'Weather warning';let p=document.createElement('p');p.textContent=row.text_en||row.text_bm||'无内容';let small=document.createElement('small');small.textContent=`有效期：${row.valid_from||'未知'} — ${row.valid_to||'未知'}（无时区字段按 MYT 解读）`;card.append(h,p,small);$('weatherResults').append(card);}}catch(e){$('weatherStatus').textContent='官方 API 本次读取未成功（网络、跨域或服务限制）：'+e.message+'。当前资料状态为「未取得」，不表示没有预警。可打开官方门户核对。';}finally{clearTimeout(timeout);btn.disabled=false;}}
async function init(){try{let [d,s,p,sources]=await Promise.all(['scenario.json','exports/stress.json','exports/predictive_metrics.json','sources.json'].map(async f=>{let r=await fetch(f);if(!r.ok)throw Error(f+': '+r.status);return r.json();}));data=d;stressResult=s;predictive=p;result=plan(data,options);$('loadState').hidden=true;$('appContent').hidden=false;render();renderStress(stressResult);$('predictiveMetrics').innerHTML=`<div><span>时间留出 Brier</span><strong>${p.holdout_brier.toFixed(4)}</strong></div><div><span>常数基线 Brier</span><strong>${p.constant_baseline_brier.toFixed(4)}</strong></div><div><span>数据状态</span><strong>完全合成</strong></div>`;$('sourcesGrid').innerHTML=sources.map(s=>`<article class="source-card"><div class="source-type">${esc(s.type)}</div><h3>${esc(s.name)}</h3><span class="badge ${s.status.includes('已')?'soft':'neutral'}">${esc(s.status)}</span><p>${esc(s.description)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener">查看原始来源 ↗</a></article>`).join('');syncControls();showView(location.hash.slice(1)||'overview');}catch(e){$('loadState').textContent='演练模型加载未完成：'+e.message+'。请刷新后重试。';}}
for(let b of document.querySelectorAll('[data-view]'))b.onclick=()=>showView(b.dataset.view);for(let b of document.querySelectorAll('[data-go]'))b.onclick=()=>showView(b.dataset.go);$('methodBtn').onclick=()=>showView('sources');for(let id of ['pressure','horizon','shelterScale','congestion','accessible'])$(id).addEventListener('input',()=>{labels();$('planStatus').textContent='设置已更改 · 点击计算应用';$('runBtn').textContent='应用新设置 →';});$('runBtn').onclick=()=>{calculate();toast('模型已重新分配；结果为静态演练方案。');};$('preset').onchange=()=>{let presets={baseline:{pressure:1,shelter_scale:1,congestion:1},severe:{pressure:1.8,shelter_scale:1,congestion:1.5},capacity:{pressure:1.1,shelter_scale:.65,congestion:1.2}};options={...options,...presets[$('preset').value]};syncControls();calculate();toast('已应用演练情景');};$('resetBtn').onclick=()=>{options={...defaults,closed_roads:[],closed_shelters:[]};syncControls();$('preset').value='baseline';highlight=null;calculate();$('mapInfo').textContent='选择社区、PPS 或走廊，查看规划资料。';toast('已恢复基准演练');};$('exportBtn').onclick=()=>{if(!result)return;download(JSON.stringify({...result,exported_at:new Date().toISOString()},null,2),'civicops_plan_exercise.json');toast('已导出含假设和限制说明的 JSON 方案');};$('csvBtn').onclick=csvDownload;$('clearRoute').onclick=()=>{highlight=null;renderMap();};$('layerRoad').onclick=()=>{showRoads=!showRoads;$('layerRoad').classList.toggle('selected',showRoads);$('layerRoad').setAttribute('aria-pressed',showRoads);renderMap();};$('layerRoute').onclick=()=>{showRoutes=!showRoutes;$('layerRoute').classList.toggle('selected',showRoutes);$('layerRoute').setAttribute('aria-pressed',showRoutes);renderMap();};$('stressBtn').onclick=async()=>{let b=$('stressBtn');b.disabled=true;b.textContent='演练计算中…';await new Promise(r=>setTimeout(r,30));try{stressResult=simulate(data,options,100,42);renderStress(stressResult);$('stressCaption').textContent=`当前已应用设置 · 浏览器引擎 · seed 42 · 100 次 · 压力 ${options.pressure.toFixed(2)}×`;toast('已完成 100 次假设压力演练');}catch(e){toast('压力演练未完成：'+e.message);}finally{b.disabled=false;b.textContent='运行当前设置 · 100 次';}};$('fetchWeather').onclick=fetchWeather;init();
